* { box-sizing: border-box; }
:root { color-scheme: light; --ink: #24343a; --muted: #687a7c; --paper: #fffdf5; --mint: #bfe8d5; --coral: #ef866e; --yellow: #f7d978; }
body { margin: 0; min-height: 100vh; padding: 32px 16px; display: grid; place-items: center; background-color: #dff1e8; background-image: radial-gradient(#a8d8c2 1.5px, transparent 1.5px); background-size: 22px 22px; color: var(--ink); font: 17px/1.45 system-ui, sans-serif; }
.board { width: min(100%, 620px); padding: clamp(22px, 5vw, 40px); background: var(--paper); border: 3px solid var(--ink); border-radius: 18px; box-shadow: 8px 8px 0 var(--ink); }
.header { display: flex; align-items: center; gap: 18px; margin-bottom: 28px; }
.pixel-mark { flex: 0 0 58px; height: 58px; display: grid; place-items: center; border: 3px solid var(--ink); border-radius: 12px; background: var(--yellow); font-size: 36px; font-weight: 900; }
.eyebrow { margin: 0 0 2px; color: var(--muted); font-size: 13px; font-weight: 800; letter-spacing: .12em; }
h1 { margin: 0; font-size: clamp(30px, 8vw, 42px); line-height: 1.1; letter-spacing: -.04em; }
.subtitle { margin: 5px 0 0; color: var(--muted); }
.settings { display: flex; align-items: center; justify-content: space-between; padding: 14px 16px; margin-bottom: 28px; border: 2px dashed #9bb6a8; border-radius: 12px; }
.settings label { font-weight: 750; }
.tip-control { display: flex; align-items: center; gap: 6px; font-weight: 800; }
.tip-control input { width: 68px; padding: 8px; text-align: right; }
input { min-width: 0; min-height: 46px; padding: 10px 12px; border: 2px solid #b4c4bc; border-radius: 9px; background: white; color: var(--ink); font: inherit; }
input:focus-visible, button:focus-visible { outline: 3px solid #db684f; outline-offset: 3px; }
.section-heading { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
h2 { margin: 0; font-size: 21px; }
#item-count { color: var(--muted); font-size: 15px; }
.item-form { display: grid; grid-template-columns: minmax(0, 1fr) 125px 48px; gap: 9px; margin-top: 14px; }
.price-input { position: relative; }
.price-input span { position: absolute; top: 10px; left: 11px; color: var(--muted); }
.price-input input { width: 100%; padding-left: 27px; }
button { border: 2px solid var(--ink); border-radius: 9px; color: var(--ink); font: inherit; font-weight: 850; cursor: pointer; transition: transform .12s, box-shadow .12s, background-color .12s; }
button:hover { transform: translateY(-2px); box-shadow: 0 3px 0 var(--ink); }
button:active { transform: translateY(1px); box-shadow: none; }
.add-button { background: var(--coral); font-size: 27px; line-height: 1; }
.hint { margin: 9px 0 12px; color: var(--muted); font-size: 14px; }
.item-list { display: grid; gap: 10px; margin: 0; padding: 0; list-style: none; }
.item-row { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 10px; align-items: center; padding: 12px; border: 2px solid #e2e9df; border-radius: 11px; background: #fff; }
.item-info { min-width: 0; }
.item-name { overflow-wrap: anywhere; font-weight: 750; }
.item-price { color: var(--muted); font-size: 15px; }
.sharers { display: flex; gap: 5px; align-items: center; }
.sharer { width: 38px; height: 38px; padding: 0; border-color: #c3d1ca; background: #f5f8f4; font-size: 14px; }
.sharer[aria-pressed="true"] { background: var(--mint); border-color: var(--ink); box-shadow: inset 0 -3px 0 #8fbea7; }
.remove-button { width: 34px; height: 34px; margin-left: 5px; border: 0; background: transparent; color: var(--muted); font-size: 20px; }
.empty-state { margin: 14px 0 0; padding: 18px; border-radius: 10px; background: #f1f6ef; color: var(--muted); text-align: center; }
.totals-section { margin-top: 30px; padding-top: 22px; border-top: 2px dashed #cad8ce; }
.pixel-heart { color: var(--coral); font-size: 22px; }
.people-totals { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; margin-top: 14px; }
.person-card { padding: 13px 10px; border: 2px solid var(--ink); border-radius: 11px; background: var(--mint); text-align: center; }
.person-card:nth-child(2) { background: #ffe5bb; }
.person-card:nth-child(3) { background: #f7d9d2; }
.person-name { display: block; color: var(--muted); font-size: 14px; font-weight: 700; }
.person-amount { display: block; margin-top: 3px; font-size: 22px; font-weight: 850; }
.bill-total { display: flex; align-items: center; justify-content: space-between; margin-top: 17px; padding: 15px 0 0; border-top: 1px solid #dce4dc; font-weight: 750; }
.bill-total strong { font-size: 23px; }
footer { margin-top: 25px; color: var(--muted); text-align: center; font-size: 14px; }
footer span { color: var(--coral); }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }
@media (max-width: 430px) { body { padding: 18px 12px; } .item-form { grid-template-columns: minmax(0, 1fr) 95px 44px; gap: 6px; } .item-row { grid-template-columns: 1fr; } .sharers { justify-content: flex-start; } .remove-button { margin-left: auto; } .person-card { padding: 11px 5px; } .person-amount { font-size: 19px; } }

const people = ['Ava', 'Bea', 'Cal'];
const items = [];
const itemForm = document.querySelector('#item-form');
const itemList = document.querySelector('#item-list');
const emptyState = document.querySelector('#empty-state');
const tipInput = document.querySelector('#tip');
const cents = value => Math.round((value + Number.EPSILON) * 100);
const money = value => `$${(value / 100).toFixed(2)}`;

function render() {
  itemList.replaceChildren();
  items.forEach((item, index) => {
    const row = document.createElement('li');
    row.className = 'item-row';
    const info = document.createElement('div');
    info.className = 'item-info';
    const name = document.createElement('div');
    name.className = 'item-name';
    name.textContent = item.name;
    const price = document.createElement('div');
    price.className = 'item-price';
    price.textContent = money(item.price);
    info.append(name, price);
    const controls = document.createElement('div');
    controls.className = 'sharers';
    controls.setAttribute('role', 'group');
    controls.setAttribute('aria-label', `Who shared ${item.name}?`);
    people.forEach((person, personIndex) => {
      const button = document.createElement('button');
      button.type = 'button';
      button.className = 'sharer';
      button.textContent = person;
      button.setAttribute('aria-pressed', String(item.shared.includes(personIndex)));
      button.setAttribute('aria-label', `${person} shared ${item.name}`);
      button.addEventListener('click', () => {
        const position = item.shared.indexOf(personIndex);
        if (position === -1) item.shared.push(personIndex);
        else item.shared.splice(position, 1);
        render();
      });
      controls.append(button);
    });
    const remove = document.createElement('button');
    remove.type = 'button';
    remove.className = 'remove-button';
    remove.textContent = '×';
    remove.setAttribute('aria-label', `Remove ${item.name}`);
    remove.addEventListener('click', () => { items.splice(index, 1); render(); });
    controls.append(remove);
    row.append(info, controls);
    itemList.append(row);
  });
  document.querySelector('#item-count').textContent = `${items.length} ${items.length === 1 ? 'item' : 'items'}`;
  emptyState.hidden = items.length > 0;
  const tipRate = Math.max(0, Number(tipInput.value) || 0) / 100;
  const totals = people.map((_, personIndex) => {
    let shareCents = 0;
    for (const item of items) {
      if (item.shared.includes(personIndex)) shareCents += Math.round(item.price / item.shared.length);
    }
    return Math.round(shareCents * (1 + tipRate));
  });
  totals.forEach((total, index) => {
    document.querySelector(`#person-${index}`).textContent = money(total);
  });
  document.querySelector('#grand-total').textContent = money(totals.reduce((sum, total) => sum + total, 0));
}

people.forEach((person, index) => {
  const card = document.createElement('div');
  card.className = 'person-card';
  const label = document.createElement('span');
  label.className = 'person-name';
  label.textContent = person;
  const amount = document.createElement('strong');
  amount.className = 'person-amount';
  amount.id = `person-${index}`;
  amount.textContent = '$0.00';
  card.append(label, amount);
  document.querySelector('#people-totals').append(card);
});

itemForm.addEventListener('submit', event => {
  event.preventDefault();
  const name = document.querySelector('#item-name').value.trim();
  const price = cents(Number(document.querySelector('#item-price').value));
  if (!name || !Number.isFinite(price) || price < 1) return;
  items.push({ name, price, shared: [0, 1, 2] });
  itemForm.reset();
  document.querySelector('#item-name').focus();
  render();
});
tipInput.addEventListener('input', render);
render();
